nInfo.new(0.2,Enum.EasingStyle.Quad,Enum.EasingDirection.Out),{BackgroundColor3=knobColor,Position=knobPos}):Play()end update()Button.MouseButton1Click:Connect(function()setter(not getter())update()end)return Button end
