local function createESP(player)if player==LocalPlayer then return end local character=player.Character if not character then return end local rootPart=character:FindFirstChild("HumanoidRootPart")if not rootPart then return end local box=Instance.new("BoxHandleAdornment")box.Size=Vector3.new(4,6,2)box.Adornee=rootPart box.Color3=player.TeamColor or Color3.fromRGB(255,255,255)box.Transparency=0.4 box.ZIndex=10 box.AlwaysOnTop=true box.Parent=rootPart local billboard=Instance.new("BillboardGui")billboard.Size=UDim2.fromOffset(150,30)billboard.Adornee=rootPart billboard.AlwaysOnTop=true billboard.Parent=rootPart local nameLabel=Instance.new("TextLabel")nameLabel.Size=UDim2.new(1,0,1,0)nameLabel.BackgroundTransparency=1 nameLabel.Text=player.Name nameLabel.TextColor3=Color3.fromRGB(255,255,255)nameLabel.TextSize=14 nameLabel.Font=Enum.Font.GothamBold nameLabel.TextStrokeTransparency=0.3 nameLabel.Parent=billboard local healthBar=Instance.new("BillboardGui")healthBar.Size=UDim2.fromOffset(80,10)healthBar.Position=UDim2.new(0,-40,1,5)healthBar.Adornee=rootPart healthBar.AlwaysOnTop=true healthBar.Parent=rootPart local healthFrame=Instance.new("Frame")healthFrame.Size=UDim2.new(1,0,1,0)healthFrame.BackgroundColor3=Color3.fromRGB(30,30,30)healthFrame.BorderSizePixel=0 healthFrame.Parent=healthBar local healthFill=Instance.new("Frame")healthFill.Size=UDim2.new(1,0,1,0)healthFill.BackgroundColor3=Color3.fromRGB(0,255,0)healthFill.BorderSizePixel=0 healthFill.Parent=healthFrame local function updateHealth()local humanoid=character:FindFirstChild("Humanoid")if humanoid then local healthPercent=humanoid.Health/humanoid.MaxHealth TweenService:Create(healthFill,TweenInfo.new(0.2,Enum.EasingStyle.Quad,Enum.EasingDirection.Out),{Size=UDim2.new(healthPercent,0,1,0)}):Play()if healthPercent>0.5 then healthFill.BackgroundColor3=Color3.fromRGB(0,255,0)elseif healthPercent>0.25 then healthFill.BackgroundColor3=Color3.fromRGB(255,255,0)else healthFill.BackgroundColor3=Color3.fromRGB(255,0,0)end end end updateHealth()table.insert(ESPObjects,{Player=player,Box=box,NameTag=billboard,HealthBar=healthBar,HealthFill=healthFill,UpdateHealth=updateHealth})task.spawn(function()while ESPObjects and Settings.ESP and player and player.Parent do updateHealth()task.wait(0.2)end end)end
local function clearESP()for _,esp in ipairs(ESPObjects)do pcall(function()if esp.Box then esp.Box:Destroy()end if esp.NameTag then esp.NameTag:Destroy()end if esp.HealthBar then esp.HealthBar:Destroy()end end)end ESPObjects={}end
local function updateESP()clearESP()if not Settings.ESP then return end for _,player in ipairs(Players:GetPlayers())do if player~=LocalPlayer and player.Character then createESP(player)end end end
local function setupAntiRagdoll(character)local humanoid=character:WaitForChild("Humanoid")humanoid.PlatformStand=false pcall(function()humanoid:SetStateEnabled(Enum.HumanoidStateType.Ragdoll,false)humanoid:SetStateEnabled(Enum.HumanoidStateType.FallingDown,false)end)humanoid.StateChanged:Connect(function(_,newState)if not Settings.AntiRagdoll then return end if newState==Enum.HumanoidStateType.Ragdoll or newState==Enum.HumanoidStateType.FallingDown or newState==Enum.HumanoidStateType.Physics then humanoid.PlatformStand=false pcall(function()humanoid:ChangeState(Enum.HumanoidStateType.GettingUp)end)for _,obj in ipairs(character:GetDescendants())do if obj:IsA("Constraint")and obj:GetAttribute("RagdollConstraint")then obj:Destroy()elseif obj:IsA("Attachment")and obj:GetAttribute("RagdollAttachment")then obj:Destroy()elseif obj:IsA("Motor6D")and not obj.Enabled and string.find(string.lower(obj.Name),"ragdoll")then obj.Enabled=true end end end end)end
local function getPromptPart(prompt)local parent=prompt.Parent if parent:IsA("BasePart")then return parent end if parent:IsA("Attachment")then return parent.Parent end if parent:IsA("Model")then return parent.PrimaryPart or parent:FindFirstChildWhichIsA("BasePart",true)end return parent:FindFirstChildWhichIsA("BasePart",true)end
local function findNearestSteal()if not HRP or not HRP.Parent then return nil end local closest=nil local closestDistance=STEAL_DISTANCE for _,obj in ipairs(workspace:GetDescendants())do if obj:IsA("ProximityPrompt")and obj.Enabled then local action=string.lower(tostring(obj.ActionText or""))local stealKeywords={"steal","grab","take","collect","rob","loot","pickpocket","snatch"}local isStealAction=false for _,keyword in ipairs(stealKeywords)do if string.find(action,keyword)then isStealAction=true break end end local promptName=string.lower(obj.Name or"")local parentName=string.lower(obj.Parent and obj.Parent.Name or"")if isStealAction or string.find(promptName,"steal")or string.find(parentName,"steal")then local part=getPromptPart(obj)if part and part:IsA("BasePart")and part.Parent then local distance=(HRP.Position-part.Position).Magnitude if distance<=closestDistance then closestDistance=distance closest=obj end end end end end return closest end
local function activatePrompt(prompt)if not prompt or not prompt:IsDescendantOf(workspace)then return false end if not prompt.Enabled then return false end local success=false if type(fireproximityprompt)=="function"then pcall(function()fireproximityprompt(prompt,1,0.05,false)success=true end)end if not success then pcall(function()prompt.HoldDuration=0.05 prompt:InputHoldBegin()task.wait(0.05)prompt:InputHoldEnd()success=true end)end if not success then pcall(function()prompt:Activate()success=true end)end return success end
local function performAutoSteal()local prompt=findNearestSteal()if not prompt then return end local maxAttempts=5 local successCount=0 for i=1,maxAttempts do if activatePrompt(prompt)then successCount=successCount+1 end task.wait(0.02)end if successCount>=2 then if prompt.Parent and prompt.Parent:IsA("BasePart")then local part=prompt.Parent local origColor=part.Color pcall(function()part.Color=Color3.fromRGB(0,255,0)task.wait(0.1)part.Color=origColor end)end end end
